#!/bin/bash
set -e
D="$(cd "$(dirname "$0")" && pwd)"
echo "Installing NOVA Shell..."
echo '' | base64 -d > "$D/novashell.py"
cat > "$D/novashell" << 'LAUNCHER'
#!/bin/bash
D="$(cd "$(dirname "$0")" && pwd)"
python3 "$D/novashell.py"
LAUNCHER
chmod +x "$D/novashell"
if [ "$EUID" -eq 0 ]; then
  cp "$D/novashell" /usr/local/bin/novashell
  mkdir -p /usr/share/icons/hicolor/256x256/apps
  cp "$D/nova-shell.png" /usr/share/icons/hicolor/256x256/apps/nova-shell.png
  cp "$D/nova-shell.desktop" /usr/share/applications/
  echo "Installed system-wide. Run 'novashell' from any terminal."
else
  echo "Installed to: $D/novashell"
  echo "For system-wide install run: sudo ./build.sh"
fi
command -v python3 &>/dev/null || echo "Python 3 required: sudo apt install python3"